#!/usr/bin/env python3

import json, subprocess, sys

def hanoi(n, src, dst, aux, moves):
    if n == 1:
        moves.append([1, src, dst])
    else:
        hanoi(n-1, src, aux, dst, moves)
        moves.append([n, src, dst])
        hanoi(n-1, aux, dst, src, moves)

def main():
    n = 8
    src = 0
    dst = 2
    aux = 1
    moves = []
    hanoi(n, src, dst, aux, moves)
    for i in range(0, len(moves), 25):
        group = moves[i:i+25]
        result = subprocess.run(['python3','./tower_of_hanoi.pyc','moves', json.dumps(group)], capture_output=True, text=True)
        print(result.stdout)
        if result.returncode != 0:
            sys.exit('Failed on group {}'.format(i//25))

if __name__ == '__main__':
    main()
